require('../../config.php');require_login();\local_worksheetlibrary\service\access_service::require_author();$versionid=required_param('versionid',PARAM_INT);$v=$DB->get_record('wslib_version',['id'=>$versionid,'state'=>'draft'],'*',MUST_EXIST);$item=$DB->get_record('wslib_item',['id'=>$v->itemid],'*',MUST_EXIST);if($item->kind!=='office')throw new moodle_exception('Not an Office worksheet');$file=\local_worksheetlibrary\service\file_service::primary($versionid);if(!$file)throw new moodle_exception('Office file missing');$cfg=get_config('local_digieraoffice');if(empty($cfg->enabled)||empty($cfg->documentserverurl)||empty($cfg->jwtsecret))throw new moodle_exception('ONLYOFFICE is not configured');$url=moodle_url::make_pluginfile_url(context_system::instance()->id,'local_worksheetlibrary','content',$versionid,'/',$file->get_filename(),false)->out(false);$callback=(new moodle_url('/local/worksheetlibrary/office_callback.php',['versionid'=>$versionid]))->out(false);$key=\local_digieraoffice\document_key::make('wslib',$versionid,(int)$v->versionno,$file->get_contenthash());$editor=['callbackUrl'=>$callback,'lang'=>current_language(),'user'=>['id'=>(string)$USER->id,'name'=>fullname($USER)],'customization'=>['autosave'=>true,'forcesave'=>true]];$doc=['fileType'=>pathinfo($file->get_filename(),PATHINFO_EXTENSION),'key'=>$key,'title'=>$item->name,'url'=>$url,'permissions'=>['edit'=>true,'download'=>true,'print'=>true]];$config=\local_digieraoffice\editor_config::build($doc,$editor,(string)$cfg->jwtsecret);$PAGE->set_context(context_system::instance());$PAGE->set_url('/local/worksheetlibrary/office.php',['versionid'=>$versionid]);$PAGE->set_title($item->name);$PAGE->set_heading($item->name);echo $OUTPUT->header();echo '<div class="wslib-office-shell"><div class="wslib-office-toolbar"><a class="btn btn-outline-secondary" href="detail.php?itemid='.$item->id.'">← Chi tiết</a><span class="badge bg-warning text-dark">DRAFT v'.$v->versionno.'</span></div><div id="wslib-office-editor" style="height:78vh"></div></div>';echo '<script src="'.s(rtrim((string)$cfg->documentserverurl,'/').'/web-apps/apps/api/documents/api.js').'"></script><script>new DocsAPI.DocEditor("wslib-office-editor",'.json_encode($config,JSON_UNESCAPED_SLASHES|JSON_UNESCAPED_UNICODE).');</script>';echo $OUTPUT->footer();
